class ManagedFile:
    def __init__(self, filename):
        self.filename = filename
    def __enter__(self):
        self.file = open(self.filename, 'w')
        return self.file
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.file.close()
with ManagedFile('hello.txt') as f:
    f.write('hello, world!')
# Demonstrates how to create and use a context manager for file operations.
